import{_ as l,a0 as i,w as s,s as p,ao as r,I as n,x as t,a1 as d,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux 用户的 3 个命令行小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 用户的 3 个命令行小技巧 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 用户的 3 个命令行小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 用户的 3 个命令行小技巧 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150527 3 Useful Hacks Every Linux User Must Know","title":"Linux 用户的 3 个命令行小技巧","tag":"201506","desc":""},"relativePath":"201506/20150527 3 Useful Hacks Every Linux User Must Know.md","filePath":"[post].md"}'),c={name:"201506/20150527 3 Useful Hacks Every Linux User Must Know.md"};function u(x,e,m,f,w,h){const o=i("Link");return s(),p("div",null,[e[15]||(e[15]=r(`<h1 id="linux-用户的-3-个命令行小技巧" tabindex="-1">Linux 用户的 3 个命令行小技巧 <a class="header-anchor" href="#linux-用户的-3-个命令行小技巧" aria-label="Permalink to “Linux 用户的 3 个命令行小技巧”">​</a></h1><p>Linux世界充满了乐趣，我们越深入进去，就会发现越多有趣的事物。我们会努力给你提供一些小技巧，让你和其他人有所不同，下面就是我们准备的3个小技巧。</p><h3 id="_1-如何在不使用cron的情况调度linux下的任务" tabindex="-1">1. 如何在不使用Cron的情况调度Linux下的任务 <a class="header-anchor" href="#_1-如何在不使用cron的情况调度linux下的任务" aria-label="Permalink to “1. 如何在不使用Cron的情况调度Linux下的任务”">​</a></h3><p>在Linux下，调度一个任务/命令称之为Cron。当我们需要调度一个任务时，我们会使用Cron，但你知道我们在不使用Cron的情况也可以调度一个在将来时间运行的任务吗？你可以按照如下建议操作……</p><p>每5秒钟运行一个命令（date）然后将结果写入到一个文件（data.txt）。为了实现这一点，我们可以直接在命令提示符运行如下单行脚本。</p><pre><code>$ while true; do date &gt;&gt; date.txt ; sleep 5 ; done &amp;
</code></pre><p>上述脚本的解释：</p><ul><li><code>while true</code> ：让脚本进入一个条件总为真的循环中，也就是制造一个死循环，将里边的命令一遍遍地重复运行。</li><li><code>do</code> ：<code>do</code>是<code>while</code>语句中的关键字，它之后的命令会被执行，在它后边可以放置一个或一系列命令。</li><li><code>date &gt;&gt; date.txt</code> ：运行date命令，并将其输出写入到data.txt文件中。注意我们使用<code>&gt;&gt;</code>，而不是<code>&gt;</code>。</li><li><code>&gt;&gt;</code> ：对文件（date.txt）进行追加写的操作，这样每次运行命令后，输出内容会被追加到文件中。如果使用<code>&gt;</code>的话，则会一遍遍地覆盖之前的内容。</li><li><code>sleep 5</code> ：让脚本处于5秒睡眠状态，然后再运行之后的命令。注意这里的时间单位只能用秒。也就是说如果你想让命令每6分钟运行一次，你应该使用<code>sleep 360</code>。</li><li><code>done</code> ：<code>while</code>循环语句块结束的标记。</li><li><code>&amp;</code> ：将整个进程放到后台运行。</li></ul><p>类似地，我们可以这样运行任何脚本。下边的例子是每100秒运行一个名为<code>script_name.sh</code>的脚本。</p><p>另外值得一提的是上面提到的脚本文件必须处于当前目录中，否则需要使用完整路径（<code>/home/$USER/…/script_name.sh</code>）。实现如上功能的单行脚本如下：</p><pre><code>$ while true; do /bin/sh script_name.sh ; sleep 100 ; done &amp;
</code></pre><p><strong>总结</strong>：上述的单行脚本并不是Cron的替代品，因为Cron工具支持众多选项，更加灵活，可定制性也更高。然而如果我们想运行某些测试，比如I/O评测，上述的单行脚本也管用。</p>`,12)),n("p",null,[e[1]||(e[1]=t("还可以参考：",-1)),d(o,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:a(()=>[...e[0]||(e[0]=[t("Linux 下 11 个定时调度任务例子",-1)])]),_:1})]),e[16]||(e[16]=r(`<h3 id="_2-如何不使用clear命令清空终端的内容" tabindex="-1">2. 如何不使用clear命令清空终端的内容 <a class="header-anchor" href="#_2-如何不使用clear命令清空终端的内容" aria-label="Permalink to “2. 如何不使用clear命令清空终端的内容”">​</a></h3><p>你如何清空终端的内容？你可能会认为这是一个傻问题。好吧，大家都清楚可以使用<code>clear</code>命令。如果养成使用<code>ctrl + l</code>快捷键的习惯，我们会节省大量时间。</p><p><code>Ctrl + l</code>快捷键的效果和<code>clear</code>命令一样。所以下一次你就可以使用<code>ctrl + l</code>来清空终端的内容了。</p><p><strong>总结</strong>：因为<code>ctrl + l</code>是一个快捷键，我们不可以在脚本中使用。所以如果我们需要在脚本中清空屏幕内容，还是需要使用<code>clear</code>命令。但我能想到的所有其他情况，<code>ctrl + l</code>都更加有效。</p><h3 id="_3-在其它目录运行一个命令-然后自动返回当前工作目录" tabindex="-1">3. 在其它目录运行一个命令，然后自动返回当前工作目录 <a class="header-anchor" href="#_3-在其它目录运行一个命令-然后自动返回当前工作目录" aria-label="Permalink to “3. 在其它目录运行一个命令，然后自动返回当前工作目录”">​</a></h3><p>这是一个很多人可能不知道的令人吃惊的技巧。你可能想在其它目录运行任何一个命令，然后再回到当前目录。要实现这样的目的，你只需要将命令放在一个圆括号里。</p><p>我们来看一个例子：</p><pre><code>avi@deb:~$ (cd /home/avi/Downloads/)
</code></pre><p>示例输出：</p><pre><code> avi@deb:~
</code></pre><p>它首先会cd到Downloads目录，然后又回到了之前的家目录。也许你认为里边的命令根本没有执行，或者是出了某种错误，因为从命令提示符看不出任何变化。让我们简单修改一下这个命令：</p><pre><code>avi@deb:~$ (cd /home/avi/Downloads/ &amp;&amp; ls -l)
</code></pre><p>示例输出：</p><pre><code>-rw-r-----  1 avi  avi     54272 May  3 18:37 text1.txt
-rw-r-----  1 avi  avi     54272 May  3 18:37 text2.txt
-rw-r-----  1 avi  avi     54272 May  3 18:37 text3.txt
avi@deb:~$
</code></pre><p>在上述命令中，它首先进入Downloads目录，然后列出文件内容，最后又回到了当前目录。并且它证明了命令成功执行了。你可以在括号中包含任何命令，执行完都会顺利返回到当前目录。</p><p>这就是全部内容了，如果你知道任何类似的Linux技巧，你可以在文章下面的评论框中分享给我们，不要忘记将本文和朋友分享 😃</p><hr>`,17)),n("p",null,[e[3]||(e[3]=t("via: ",-1)),d(o,{href:"http://www.tecmint.com/useful-linux-hacks-commands/"},{default:a(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/useful-linux-hacks-commands/",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=t("作者：",-1)),d(o,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[4]||(e[4]=[t("Avishek Kumar",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),d(o,{href:"https://github.com/goreliu"},{default:a(()=>[...e[5]||(e[5]=[t("goreliu",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),d(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),d(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创翻译，",-1)),d(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const C=l(c,[["render",u]]);export{L as __pageData,C as default};
